/**
 * Draw scatter plot shape in canvas context
 * @param ctx - canvas context
 * @param x - x position
 * @param y - y position
 * @param radius - circle radius
 */
export function scatterPlotShape(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  radius: number,
) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, 2 * Math.PI);
  ctx.closePath();
}

/**
 * Draw line shape in canvas context
 * @param ctx - canvas context
 * @param x0 - x position from
 * @param x1 - x position to
 * @param y0 - y position from
 * @param y1 - y position to
 */
export function lineShape(
  ctx: CanvasRenderingContext2D,
  x0: number,
  x1: number,
  y0: number,
  y1: number,
) {
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.closePath();
}

/**
 * Draw area shape in canvas context
 * @param ctx - canvas context
 * @param points - group of points that will make area shape
 * @param x - x accessor that will provide X position from point
 * @param y1 - y1 accessor that will provide Y1 position from point
 * @param y0 - y0 accessor that will provide Y0 position from point
 */
export function areaShape<Datum>(
  ctx: CanvasRenderingContext2D,
  points: Datum[],
  x: (point: Datum, index: number) => number,
  y1: (point: Datum, index: number) => number,
  y0: (point: Datum, index: number) => number,
) {
  ctx.beginPath();

  //from X-min to X-max
  points.forEach((point, index) => {
    const [nextX, nextY0] = [x(point, index), y0(point, index)];
    ctx.lineTo(nextX, nextY0);
  });

  //from X-max to Y-max
  const lastIndex = points.length - 1;
  ctx.lineTo(x(points[lastIndex], lastIndex), y1(points[lastIndex], lastIndex));

  //from X-max to X-min
  [...points].reverse().forEach((point, index) => {
    const [nextX, nextY1] = [x(point, index), y1(point, index)];

    ctx.lineTo(nextX, nextY1);
  });

  // from X-min to y-min
  const firstIndex = 0;
  ctx.lineTo(
    x(points[firstIndex], firstIndex),
    y0(points[firstIndex], firstIndex),
  );
  ctx.closePath();
}
